const lista = document.querySelector('#lista-alunos');

async function carregarTudo() {
  const [respostaAlunos, respostaCursos] = await Promise.all([
    fetch('http://localhost:3000/alunos'),
    fetch('http://localhost:3000/cursos'),
  ]);

  const alunos = await respostaAlunos.json();
  const cursos = await respostaCursos.json();

  for (const aluno of alunos) {
    const curso = cursos.find((item) => item.id === aluno.cursoId);
    const li = document.createElement('li');
    li.textContent = aluno.nome + ' — ' + curso.nome;
    lista.appendChild(li);
  }
}

carregarTudo();
